"use client";
// Printable dental chart (odontogram). Each tooth: captured front-view PNG
// (/teeth/<fdi>.png, trimmed to fill the frame) + FDI number + the real
// QuickSurfaceSelector SVG (rendered grayscale — charts print black & white).
// Upper arch: tooth→number→selector; lower arch mirrored. Two modes: "plain"
// (blank) and "historical" (recorded surfaces filled, data-teeth highlighted,
// issues listed). Optional patient header. Selecting an option goes straight to
// the system print dialog (its own preview).

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { getAppointmentPatient } from "@/lib/appointment-patients";
import { TPTooltip } from "@/components/tp-ui";
import { QuickSurfaceSelector } from "./QuickSurfaceSelector";
import { OralExamReport } from "./FlatDentitionChart";
import { loadDentalPreviewSnapshot } from "@/components/tp-rxpad/rx-preview-store";
import { RxPreviewDocument } from "@/components/tp-rxpad/RxPreviewDocument";
import { getComposedRxPreviewSnapshot } from "@/components/tp-rxpad/rx-preview-composer";

const EXAM_CHART_PREFIX = "dental.exam.chart.";
const UPPER_ROW = ["18", "17", "16", "15", "14", "13", "12", "11", "21", "22", "23", "24", "25", "26", "27", "28"];
const LOWER_ROW = ["48", "47", "46", "45", "44", "43", "42", "41", "31", "32", "33", "34", "35", "36", "37", "38"];

function loadChart(patientId) {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(`${EXAM_CHART_PREFIX}${patientId || "apt-1"}`);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

function computeZones(chart) {
  const zonesByTooth = {};
  const missing = new Set();
  const add = (fdi, z) => { (zonesByTooth[fdi] = zonesByTooth[fdi] || new Set()).add(z); };
  Object.entries(chart?.findingsByTooth || {}).forEach(([fdi, list]) => {
    (list || []).forEach((f) => { if (f && f.type && f.type !== "Normal" && f.zoneId) add(fdi, f.zoneId); });
  });
  (chart?.entries || []).forEach((e) => { (e.surfaces || []).forEach((z) => add(e.toothFdi, z)); });
  Object.entries(chart?.toothDiagnoses || {}).forEach(([fdi, diags]) => {
    (diags || []).forEach((d) => {
      if (d === "Missing" || d === "Extraction") missing.add(fdi);
      else add(fdi, "whole");
    });
  });
  return { zonesByTooth, missing };
}

function computeIssues(chart) {
  const byTooth = {};
  const push = (fdi, s) => { (byTooth[fdi] = byTooth[fdi] || []).push(s); };
  Object.entries(chart?.toothDiagnoses || {}).forEach(([fdi, d]) => { (d || []).forEach((x) => push(fdi, x)); });
  Object.entries(chart?.findingsByTooth || {}).forEach(([fdi, list]) => {
    (list || []).forEach((f) => { if (f && f.type && f.type !== "Normal") push(fdi, f.type); });
  });
  (chart?.entries || []).forEach((e) => { if (e?.name) push(e.toothFdi, e.name); });
  const teeth = Object.entries(byTooth).map(([fdi, arr]) => ({ fdi, items: [...new Set(arr)] }))
    .sort((a, b) => a.fdi.localeCompare(b.fdi));
  const oral = (chart?.oralEntries || []).map((e) => e.name).filter(Boolean);
  return { teeth, oral, oralNotes: (chart?.oralNotes || "").trim() };
}

const HILITE = "rgba(124,58,237,0.10)";
const TOOTH_STROKE = "drop-shadow(1.2px 0 0 #7c3aed) drop-shadow(-1.2px 0 0 #7c3aed) drop-shadow(0 1.2px 0 #7c3aed) drop-shadow(0 -1.2px 0 #7c3aed)";
// Exact width/height of each trimmed tooth PNG → flex weight, so every tooth
// renders at the SAME height (molars get wider cells → not small) and the row
// fits the A4 sheet width.
const TOOTH_ASPECT = { "11": 0.371, "12": 0.371, "13": 0.341, "14": 0.354, "15": 0.373, "16": 0.505, "17": 0.513, "18": 0.515, "21": 0.371, "22": 0.371, "23": 0.341, "24": 0.354, "25": 0.373, "26": 0.505, "27": 0.513, "28": 0.515, "31": 0.3, "32": 0.287, "33": 0.307, "34": 0.334, "35": 0.342, "36": 0.668, "37": 0.55, "38": 0.658, "41": 0.3, "42": 0.287, "43": 0.307, "44": 0.334, "45": 0.342, "46": 0.668, "47": 0.55, "48": 0.658 };
function toothCellAspect(fdi) { return TOOTH_ASPECT[fdi] || 0.45; }

const MAX_HALF_ASPECT_SUM = 3.45; // widest half-arch aspect sum (lower arch)

function ToothCell({ fdi, arch, zones, isMissing, mode, h }) {
  const hasData = mode === "historical" && (isMissing || (zones && zones.size > 0));
  const pos = Number(fdi[1]) || 6;
  const img = (
    <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "center", borderRadius: 8, background: hasData ? HILITE : "transparent", boxSizing: "border-box", padding: 2 }}>
      <img src={`/teeth/${fdi}.png?v=2`} alt={fdi} style={{ height: h, width: "auto", display: "block", opacity: isMissing ? 0.4 : 1, filter: hasData ? TOOTH_STROKE : undefined }} />
    </div>
  );
  const num = (
    <div style={{ font: `${hasData ? 800 : 600} 11px Inter, sans-serif`, color: hasData ? "#1e293b" : "#94a3b8", textAlign: "center", lineHeight: 1 }}>{fdi}</div>
  );
  // QuickSurfaceSelector is ~76px wide; scale it down and render grayscale (B&W print).
  const selector = (
    <div style={{ width: 38, height: 84, position: "relative", overflow: "hidden", display: "flex", justifyContent: "center", filter: "grayscale(1)" }}>
      <div style={{ transform: "scale(0.48)", transformOrigin: "top center" }}>
        <QuickSurfaceSelector
          selectedZones={mode === "historical" ? (zones || new Set()) : new Set()}
          onToggleZone={() => {}}
          arch={arch}
          toothPosition={pos}
          zonesWithFindings={new Set()}
        />
      </div>
    </div>
  );
  const stack = arch === "maxillary" ? [img, num, selector] : [selector, num, img];
  return (
    <div style={{ flex: "0 0 auto", display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
      {stack.map((el, i) => <div key={i} style={{ display: "flex", justifyContent: "center" }}>{el}</div>)}
    </div>
  );
}

function ArchRow({ fdis, arch, zonesByTooth, missing, mode, h }) {
  const cell = (fdi) => (
    <ToothCell key={fdi} fdi={fdi} arch={arch} zones={zonesByTooth[fdi]} isMissing={missing.has(fdi)} mode={mode} h={h} />
  );
  return (
    <div style={{ display: "flex", alignItems: "stretch" }}>
      <div style={{ flex: "1 1 0", display: "flex", justifyContent: "space-between" }}>{fdis.slice(0, 8).map(cell)}</div>
      <div style={{ width: 1, background: "#e2e8f0", margin: "0 6px" }} />
      <div style={{ flex: "1 1 0", display: "flex", justifyContent: "space-between" }}>{fdis.slice(8).map(cell)}</div>
    </div>
  );
}

