// Dental Examination history rendered identically to the Rx preview: each tooth
// is a bullet, with Past Procedures / Findings / Procedures / Overall Tooth Notes
// as sub-headings and every entry on its own sub-bullet (name bold + bracket meta).
function DentalHistorySections({ patientId }) {
  const snap = typeof window !== "undefined" ? loadDentalPreviewSnapshot(patientId) : null;
  const sections = snap?.sections || [];
  if (!sections.length) return null;
  const head = { margin: 0, fontSize: 11.5, color: "#334155", display: "flex", gap: 5, alignItems: "baseline", lineHeight: 1.4, fontWeight: 600 };
  const item = { margin: 0, fontSize: 11.5, color: "#475569", display: "flex", gap: 5, alignItems: "baseline", lineHeight: 1.4 };
  const sub = (label, items) => (items && items.length) ? (
    <div>
      <p style={head}><span style={{ color: "#94a3b8" }}>•</span><span>{label}</span></p>
      <div style={{ paddingLeft: 14, display: "flex", flexDirection: "column", gap: 1, marginTop: 1 }}>
        {items.map((it, i) => (
          <p key={i} style={item}><span style={{ color: "#94a3b8" }}>•</span><span><span style={{ fontWeight: 600, color: "#334155" }}>{it.title}</span>{(it.metaParts && it.metaParts.length) ? ` (${it.metaParts.join(" | ")})` : ""}</span></p>
        ))}
      </div>
    </div>
  ) : null;
  return (
    <div style={{ marginTop: 16, paddingTop: 12, borderTop: "1px solid #e2e8f0" }}>
      <h3 style={{ font: "700 13px Inter, sans-serif", color: "#334155", margin: "0 0 8px" }}>Dental Examination</h3>
      <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
        {sections.map((b, bi) => (
          <div key={bi}>
            <p style={{ margin: 0, fontSize: 12, fontWeight: 700, color: "#1e293b", display: "flex", gap: 6, alignItems: "baseline" }}><span style={{ color: "#1e293b" }}>•</span>{b.toothLabel}</p>
            <div style={{ paddingLeft: 14, display: "flex", flexDirection: "column", gap: 2, marginTop: 2 }}>
              {sub("Past Procedures", b.treatmentHistory)}
              {sub("Findings", b.findings)}
              {sub("Procedures", b.procedures)}
              {b.overallToothNote ? (
                <div>
                  <p style={head}><span style={{ color: "#94a3b8" }}>•</span><span>Overall Tooth Notes</span></p>
                  <div style={{ paddingLeft: 14, marginTop: 1 }}><p style={item}><span style={{ color: "#94a3b8" }}>•</span><span>{b.overallToothNote}</span></p></div>
                </div>
              ) : null}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function DentalChartSheet({ patientId, mode, includePatient }) {
  const { zonesByTooth, missing } = mode === "historical"
    ? computeZones(loadChart(patientId) || {})
    : { zonesByTooth: {}, missing: new Set() };
  // Uniform tooth height sized from the row width so every tooth is identical
  // and the widest row still fits across the A4 sheet.
  const rowsRef = useRef(null);
  const [toothH, setToothH] = useState(120);
  useEffect(() => {
    const measure = () => {
      const w = rowsRef.current?.clientWidth || 992;
      const half = (w - 14) / 2;
      setToothH(Math.max(60, Math.min(150, (half / MAX_HALF_ASPECT_SUM) * 0.9)));
    };
    measure();
    let ro;
    if (typeof ResizeObserver !== "undefined" && rowsRef.current) { ro = new ResizeObserver(measure); ro.observe(rowsRef.current); }
    return () => ro?.disconnect();
  }, []);
  return (
    <div className="dcp-sheet" style={{ background: "#fff", color: "#0f172a", padding: 24, width: 1040, maxWidth: "100%", margin: "0 auto", fontFamily: "Inter, sans-serif" }}>
      {includePatient && <PatientHeader patientId={patientId} />}
      <h2 style={{ font: "700 14px Inter, sans-serif", color: "#334155", margin: "14px 0 12px" }}>
        Dental Chart{mode === "plain" ? " (Blank)" : ""}
      </h2>
      <div ref={rowsRef} style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <ArchRow fdis={UPPER_ROW} arch="maxillary" zonesByTooth={zonesByTooth} missing={missing} mode={mode} h={toothH} />
        <div style={{ height: 1, background: "#e2e8f0" }} />
        <ArchRow fdis={LOWER_ROW} arch="mandibular" zonesByTooth={zonesByTooth} missing={missing} mode={mode} h={toothH} />
      </div>
      {mode === "historical" && <DentalHistorySections patientId={patientId} />}
      {mode === "historical" && <OralExamReport patientId={patientId} />}
    </div>
  );
}

// Print stylesheet: hide everything else, expand the print root to one A4 page
// width, push each <article> (one A4 sheet from RxPreviewDocument) to its own
// physical page so the printout reads exactly like the Preview Rx drawer.
const PRINT_STYLE = `
@media print {
  body > *:not(.dcp-print-root) { display: none !important; }
  .dcp-print-root { position: static !important; opacity: 1 !important; z-index: auto !important; width: 100% !important; pointer-events: auto !important; left: auto !important; top: auto !important; }
  .dcp-print-root > div { max-width: 100% !important; gap: 0 !important; }
  .dcp-print-root article { box-shadow: none !important; border-radius: 0 !important; aspect-ratio: auto !important; height: auto !important; min-height: 0 !important; break-after: page !important; page-break-after: always !important; overflow: visible !important; }
  .dcp-print-root article:last-child { break-after: auto !important; page-break-after: avoid !important; }
  @page { size: A4 portrait; margin: 10mm; }
  * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
}`;

// Empty Rx snapshot shape — used by the "plain" mode so the printed page has
// only the dental chart (no historical/clinical sections) but still matches the
// Preview Rx letterhead + patient + footer pattern exactly.
function emptySnapshot(patientId) {
  return {
    patientId,
    updatedAt: new Date().toISOString(),
    symptoms: [], examinations: [], diagnoses: [], labInvestigations: [],
    medications: [], advice: [],
    vitals: [], labResults: [],
    dentalExamination: [],
  };
}

// Renders the Rx-preview document off-screen at A4 width and fires the system
// print dialog. The printed output mirrors the Preview Rx drawer; "historical"
// includes all dental + oral history sections above the chart, "plain" prints
// just the chart on the letterhead.
function PrintRunner({ patientId, mode, includePatient, onDone }) {
  useEffect(() => {
    const after = () => onDone();
    window.addEventListener("afterprint", after);
    // Allow the PNG odontogram + measurement effects to settle before printing.
    const t = setTimeout(() => { try { window.print(); } catch {} }, 750);
    const fallback = setTimeout(onDone, 60000);
    return () => { clearTimeout(t); clearTimeout(fallback); window.removeEventListener("afterprint", after); };
  }, [onDone]);
  const snapshot = mode === "historical"
    ? (getComposedRxPreviewSnapshot(patientId) ?? emptySnapshot(patientId))
    : emptySnapshot(patientId);
  // Patient header is part of RxPreviewDocument; when includePatient is false
  // we still keep the letterhead/footer but render with a stripped patientId
  // marker would be ideal — for v0 we always include the patient block since
  // the Preview Rx pattern includes it by design.
  void includePatient;
  return createPortal(
    <div className="dcp-print-root" style={{ position: "fixed", left: 0, top: 0, width: 760, opacity: 0, pointerEvents: "none", zIndex: -1, background: "#fff" }}>
      <style>{PRINT_STYLE}</style>
      <RxPreviewDocument snapshot={snapshot} settings={{ view: "list", showDentalChart: true }} />
    </div>,
    document.body
  );
}

export function DentalChartPrintButton({ patientId }) {
  const [open, setOpen] = useState(false);
  const [includePatient, setIncludePatient] = useState(true);
  const [printReq, setPrintReq] = useState(null);
  const rootRef = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (rootRef.current && !rootRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const choose = (mode) => { setOpen(false); setPrintReq({ mode, includePatient }); };
  const item = (label, sub, mode) => (
    <button type="button" onClick={() => choose(mode)} style={{ display: "block", width: "100%", textAlign: "left", padding: "9px 12px", border: "none", background: "transparent", cursor: "pointer", borderRadius: 8 }}
      onMouseEnter={(e) => { e.currentTarget.style.background = "rgba(100,116,139,0.10)"; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}>
      <div style={{ font: "700 12.5px Inter, sans-serif", color: "#1e293b" }}>{label}</div>
      <div style={{ font: "400 11px Inter, sans-serif", color: "#94a3b8", marginTop: 1 }}>{sub}</div>
    </button>
  );

  return (
    <div ref={rootRef} style={{ position: "relative" }}>
      {open && (
        <div style={{ position: "absolute", bottom: "calc(100% + 8px)", left: 0, width: 264, background: "#fff", border: "1px solid #e2e8f0", borderRadius: 12, boxShadow: "0 12px 34px rgba(2,6,23,0.18)", padding: 6, zIndex: 40 }}>
          {item("Plain dental chart", "Blank odontogram template", "plain")}
          {item("Historical dental chart", "With recorded findings & history", "historical")}
          <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px", borderTop: "1px solid #f1f5f9", cursor: "pointer", font: "600 11.5px Inter, sans-serif", color: "#475569" }}>
            <input type="checkbox" checked={includePatient} onChange={(e) => setIncludePatient(e.target.checked)} />
            Include patient information
          </label>
        </div>
      )}
      <TPTooltip title="Print dental chart" arrow placement="top">
        <button type="button" aria-label="Print dental chart" onClick={() => setOpen((o) => !o)}
          style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 40, height: 40, borderRadius: 10, border: "none", background: "transparent", color: "#334155", cursor: "pointer" }}>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M6 9V3.5C6 3.22 6.22 3 6.5 3h11c.28 0 .5.22.5.5V9M6 18H4.5C3.67 18 3 17.33 3 16.5v-5C3 10.67 3.67 10 4.5 10h15c.83 0 1.5.67 1.5 1.5v5c0 .83-.67 1.5-1.5 1.5H18M7 15h10v5.5c0 .28-.22.5-.5.5h-9a.5.5 0 0 1-.5-.5V15Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </TPTooltip>
      {printReq && (
        <PrintRunner patientId={patientId} mode={printReq.mode} includePatient={printReq.includePatient} onDone={() => setPrintReq(null)} />
      )}
    </div>
  );
}
